contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint w) public {
        require(tos.length > 0);
        require(w != 0);

        // Token (this contract) reverts the transferFrom when the value is 0:
        // then C.transfer must revert.
        bool r0;
        try c.transfer(from, address(this), tos, 0) { r0 = false; } catch { r0 = true; }

        // Token returns success when the value is w != 0:
        // then C.transfer must not revert.
        bool r1;
        try c.transfer(from, address(this), tos, w) { r1 = false; } catch { r1 = true; }

        assert(r0 && !r1);
    }

    fallback() external payable {
        // Simulated token: transferFrom(address,address,uint256)
        // calldata layout: selector(4) + from(32) + to(32) + value(32)
        if (msg.data.length >= 132) {
            uint val = abi.decode(msg.data[100:132], (uint));
            if (val == 0) {
                revert();
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address[] tos;
    address lastFrom;
    address lastTo;
    uint lastVal;
    uint callCount;

    constructor(C _c) { c = _c; }

    function run(address from, address to, uint v) public {
        require(to != address(0));
        delete tos;
        tos.push(to);
        callCount = 0;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && callCount == 1 && lastFrom == from && lastTo == to && lastVal == v);
    }

    fallback() external payable {
        // Simulated token: transferFrom(address,address,uint256)
        if (msg.data.length >= 132) {
            bytes4 sel = bytes4(msg.data[0:4]);
            if (sel == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                lastFrom = abi.decode(msg.data[4:36], (address));
                lastTo = abi.decode(msg.data[36:68], (address));
                lastVal = abi.decode(msg.data[68:100], (uint));
                callCount++;
            }
        }
    }

    receive() external payable {}
}

