contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {
        // Handles transferFrom(address,address,uint256) called by C.
        // Revert deliberately when the value encodes a 'fail' sentinel,
        // otherwise return true.
        (, bytes memory data) = address(0x0).call(""); // unreachable placeholder
        data; // silence warnings
    }

    function run(address from, uint v, uint n) public payable {
        require(n > 0 && n <= 3);
        require(v != 0);

        // Case 1: empty recipient list must revert.
        address[] memory empty = new address[](0);
        bool revertedEmpty;
        try c.transfer(from, address(this), empty, v) { revertedEmpty = false; }
        catch { revertedEmpty = true; }

        // Case 2: non-empty list, token (this contract) accepts each
        // transferFrom -> call must succeed and return true.
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(1000 + i));
        }
        bool ok;
        bool returnedTrue;
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            ok = true;
            returnedTrue = r;
        } catch {
            ok = false;
            returnedTrue = false;
        }

        assert(revertedEmpty && ok && returnedTrue);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint public cbCount;
    address public lastFrom;
    address public lastTo;
    uint public lastV;
    bytes4 constant TF = bytes4(keccak256("transferFrom(address,address,uint256)"));

    constructor(C _c) { c = _c; }

    fallback() external payable {
        require(bytes4(msg.data) == TF);
        (lastFrom, lastTo, lastV) = abi.decode(msg.data[4:], (address, address, uint256));
        cbCount = cbCount + 1;
        assembly {
            mstore(0x00, 1)
            return(0x00, 0x20)
        }
    }

    function run(address from, address[] memory tos, uint v) public payable {
        require(tos.length > 0 && tos.length <= 5);
        require(v > 0);
        cbCount = 0;
        bool r = c.transfer(from, address(this), tos, v);
        assert(r && cbCount == tos.length && lastTo == tos[tos.length - 1] && lastFrom == from && lastV == v);
    }

    receive() external payable {}
}

